      ]
    },
    {
      "claim": "We should mandate real-time circuit breakers and iterative, performance-based benchmarks that adjust to actual behavior in the field.",
      "targets": [
        "AN-11"
      ]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Financial liability for existential risks can be accurately modeled and enforced through symmetric litigation exposure before a failure occurs.",
      "if_wrong": "If risk cannot be internalized through financial mechanisms, then market-driven safety regimes lose their primary enforcement leverage against catastrophic outcomes."
